-- Run this once in the Supabase Dashboard: SQL Editor > New query.
--
-- The frontend uses Laravel authentication, not Supabase Auth. Therefore the
-- browser reaches Storage as the `anon` role and needs these object policies.
-- Paths are constrained to the format generated by src/utils/studyFiles.ts.
-- For per-user authorization, move uploads behind the Laravel API and use the
-- server-only SUPABASE_SECRET_KEY there; Storage cannot validate Laravel tokens.

drop policy if exists "class browser upload" on storage.objects;
drop policy if exists "class browser read" on storage.objects;

create policy "class browser upload"
on storage.objects
for insert
to anon, authenticated
with check (
  bucket_id = 'class'
  and name ~ '^user-[0-9]+/(semester-[0-9]+-[0-9]+|semester-unsorted)/(subject-[0-9]+|subject-general)/[^/]+$'
);

create policy "class browser read"
on storage.objects
for select
to anon, authenticated
using (bucket_id = 'class');
